def moving_average(data, window_size):
    """Calculates the moving average of a 1D array, handling NaN values."""
    # Filter out NaN values before computing moving average
    valid_mask = ~np.isnan(data)
    if not np.any(valid_mask):
        return np.array([])
    
    # Use a sliding window that skips NaN values
    result = []
    for i in range(len(data) - window_size + 1):
        window = data[i:i+window_size]
        result.append(np.nanmean(window))
    return np.array(result)


