def compute_weighted_contribution(chosen_point_C, neighbors_C_matrix, neighbors_K_values, cont_method='positive'):
    """
    Compute the weighted contribution following BAYES_MISP logic exactly.
    
    This computes how much a chosen point would contribute if selected, by evaluating
    the weighted state changes across all its neighbors.
    
    Args:
        chosen_point_C: numpy array of shape (num_classes,) - C vector of the point being evaluated (provides weights)
        neighbors_C_matrix: numpy array of shape (num_neighbors, num_classes) - C vectors of all neighbors
        neighbors_K_values: numpy array of shape (num_neighbors,) - K values between chosen point and each neighbor
        cont_method: str - continuation method ('positive', 'abs', etc.)
    
    Returns:
        float - the total weighted contribution across all neighbors
    
    Formula (matching BAYES_MISP batched_diffs_efficient_weighted_sparse):
        weights = chosen_point_C / sum(chosen_point_C)
        
        For each neighbor j with K value k_j:
            For each class c:
                new_state[j, c] = (max(-k_j, C[j,c] - max(C[j])) + max(C[j]) + k_j) / (sum(C[j]) + k_j) - max(C[j])/sum(C[j])
                contribution[j, c] = max(0, new_state[j, c])  # positive continuation
            
            weighted_contribution[j] = sum_c (weights[c] * contribution[j, c])
        
        total_contribution = sum_j weighted_contribution[j]
    """
    chosen_point_C = np.array(chosen_point_C, dtype=np.float64)
    neighbors_C_matrix = np.array(neighbors_C_matrix, dtype=np.float64)
    neighbors_K_values = np.array(neighbors_K_values, dtype=np.float64)
    
    # Compute weights from chosen point's C vector
    sum_chosen = np.sum(chosen_point_C)
    if sum_chosen == 0:
        return 0.0
    weights = chosen_point_C / sum_chosen  # (num_classes,)
    
    # Initialize total contribution
    total_contribution = 0.0
    
    # Process each neighbor
    for j in range(neighbors_C_matrix.shape[0]):
        C_j = neighbors_C_matrix[j]  # (num_classes,)
        k_j = neighbors_K_values[j]
        
        if k_j == 0:
            continue
        
        # Current state of neighbor j
        sum_C_j = np.sum(C_j)
        max_C_j = np.max(C_j)
        
        if sum_C_j == 0:
            continue
        
        old_max_prob = max_C_j / sum_C_j
        
        # Compute new state for each class after adding k_j
        C_diff = C_j - max_C_j  # C[j,c] - max(C[j]) for all classes c
        new_state = np.maximum(-k_j, C_diff) + max_C_j + k_j  # max(-k_j, C[j,c] - max_C_j) + max_C_j + k_j
        new_state = new_state / (sum_C_j + k_j)  # Divide by future sum
        new_state = new_state - old_max_prob  # Subtract old max probability
        
        # Apply continuation method
        if cont_method == 'positive':
            new_state = np.maximum(0, new_state)
        elif cont_method == 'abs':
            new_state = np.abs(new_state)
        
        # Weight by chosen point's probabilities and sum across classes
        weighted_contribution_j = np.sum(weights * new_state)
        total_contribution += weighted_contribution_j
    
    return total_contribution


def compute_kernel(x1, x2, h, batch_size=512):
    x1, x2 = x1.unsqueeze(0).to('cpu'), x2.unsqueeze(0).to('cpu')  # 1 x n x d, 1 x n' x d
    dist_matrix = []
    batch_round = x2.shape[1] // batch_size + int(x2.shape[1] % batch_size > 0)
    for i in range(batch_round):
        # distance comparisons are done in batches to reduce memory consumption
        x2_subset = x2[:, i * batch_size: (i + 1) * batch_size]
        dist = torch.cdist(x1, x2_subset)
