# Plot: Average Contribution Comparison
# For each method, create a plot comparing how all methods' C matrices look
# at the neighborhoods selected by that method
print("\n" + "="*80)
print("Generating Average Contribution Comparison Graphs")
print("="*80)

for selecting_method_name, selecting_method_data in method_data.items():
    if len(selecting_method_data['average_neighbors_C']) == 0:
        continue
    
    print(f"\nProcessing graphs for method: {selecting_method_name}")
    
    # Create figure with subplots for better organization
    fig, axes = plt.subplots(2, 2, figsize=(16, 12))
    fig.suptitle(f'Average Contribution Analysis - Points Selected by {selecting_method_name}', fontsize=14, fontweight='bold')
    
    # Prepare data for all methods
    method_contributions = {method: [] for method in methods_names}
    method_num_neighbors = []
    x_indices = []
    
    for idx, entry in enumerate(selecting_method_data['average_neighbors_C']):
        methods_data = entry['methods_data']
        neigh_num = entry['neigh_num']
        
        method_num_neighbors.append(neigh_num)
        x_indices.append(idx * 100)  # Since we sample every 100 iterations
        
        # Get the selecting method's chosen point C vector (for weights)
        selecting_chosen_C = methods_data[selecting_method_name]['chosen_point_C']
        
        for method in methods_names:
            if method in methods_data:
                neighbors_C = methods_data[method]['neighbors_C']  # (num_neighbors, num_classes)
                neighbors_K = methods_data[method]['neighbors_K']  # (num_neighbors,)
                # Compute weighted contribution following BAYES_MISP logic exactly
                # Weights come from the selecting method's C vector for the chosen point
                contribution = compute_weighted_contribution(
                    selecting_chosen_C, neighbors_C, neighbors_K, cont_method='positive'
                )
                method_contributions[method].append(contribution)
            else:
                method_contributions[method].append(np.nan)
    
    # Plot 1: Average Contribution over iterations
    ax1 = axes[0, 0]
    for method in methods_names:
        if len(method_contributions[method]) > 0:
            contributions = np.array(method_contributions[method])
            # Filter out nan values for smoothing
            valid_mask = ~np.isnan(contributions)
            if np.any(valid_mask):
                smoothed = moving_average(contributions[valid_mask], 3) if len(contributions[valid_mask]) > 3 else contributions[valid_mask]
                ax1.plot(np.array(x_indices)[valid_mask][:len(smoothed)], smoothed, label=method, linewidth=2)
    ax1.set_xlabel('Iteration', fontsize=10)
    ax1.set_ylabel('Avg Contribution (1/(sum+1) * n_neighbors)', fontsize=10)
    ax1.set_title('Average Contribution Over Time', fontsize=11, fontweight='bold')
    ax1.legend(fontsize=8, loc='best')
    ax1.grid(True, alpha=0.3)
    
    # Plot 2: Number of neighbors over iterations
    ax2 = axes[0, 1]
    ax2.plot(x_indices, method_num_neighbors, color='darkblue', linewidth=2)
    ax2.set_xlabel('Iteration', fontsize=10)
    ax2.set_ylabel('Number of Neighbors', fontsize=10)
    ax2.set_title('Number of Neighbors at Selected Points', fontsize=11, fontweight='bold')
    ax2.grid(True, alpha=0.3)
    
    # Plot 3: Average contribution normalized by number of neighbors
    ax3 = axes[1, 0]
    for method in methods_names:
        if len(method_contributions[method]) > 0:
            contributions = np.array(method_contributions[method])
            neighbors = np.array(method_num_neighbors)
            # Normalize: divide by number of neighbors to get pure 1/(sum+1)
            normalized = np.where(neighbors > 0, contributions / neighbors, np.nan)
            valid_mask = ~np.isnan(normalized)
            if np.any(valid_mask):
                smoothed = moving_average(normalized[valid_mask], 3) if len(normalized[valid_mask]) > 3 else normalized[valid_mask]
                ax3.plot(np.array(x_indices)[valid_mask][:len(smoothed)], smoothed, label=method, linewidth=2)
    ax3.set_xlabel('Iteration', fontsize=10)
    ax3.set_ylabel('Normalized Contribution (1/(sum+1))', fontsize=10)
    ax3.set_title('Normalized Contribution (Independent of Neighbors)', fontsize=11, fontweight='bold')
    ax3.legend(fontsize=8, loc='best')
    ax3.grid(True, alpha=0.3)
    
    # Plot 4: Box plot comparison (last 10 samples)
    ax4 = axes[1, 1]
    last_n_samples = 10
    boxplot_data = []
    boxplot_labels = []
    for method in methods_names:
        if len(method_contributions[method]) > 0:
            contributions = np.array(method_contributions[method])
            valid_contributions = contributions[~np.isnan(contributions)]
            if len(valid_contributions) > 0:
                # Take last N samples or all if less
                last_samples = valid_contributions[-last_n_samples:] if len(valid_contributions) >= last_n_samples else valid_contributions
                boxplot_data.append(last_samples)
                boxplot_labels.append(method)
    
    if len(boxplot_data) > 0:
        bp = ax4.boxplot(boxplot_data, labels=boxplot_labels, patch_artist=True)
        for patch in bp['boxes']:
            patch.set_facecolor('lightblue')
        ax4.set_ylabel('Avg Contribution', fontsize=10)
        ax4.set_title(f'Distribution Comparison (Last {last_n_samples} Samples)', fontsize=11, fontweight='bold')
        ax4.tick_params(axis='x', rotation=45, labelsize=8)
        ax4.grid(True, alpha=0.3, axis='y')
    
    plt.tight_layout()
    plt.show()
    
    # Additional plot: Contribution with neighbor count as scatter
    plt.figure(figsize=(12, 6))
    for method in methods_names:
        if len(method_contributions[method]) > 0:
            contributions = np.array(method_contributions[method])
            valid_mask = ~np.isnan(contributions)
            if np.any(valid_mask):
                # Size of points proportional to number of neighbors
                sizes = np.array(method_num_neighbors)[valid_mask] / 10  # Scale down for visualization
                plt.scatter(np.array(x_indices)[valid_mask], contributions[valid_mask], 
                           s=sizes, alpha=0.6, label=method)
    plt.xlabel('Iteration', fontsize=12)
    plt.ylabel('Avg Contribution (1/(sum+1) * n_neighbors)', fontsize=12)
    plt.title(f'Average Contribution with Neighbor Count - Points Selected by {selecting_method_name}', 
              fontsize=13, fontweight='bold')
    plt.legend(fontsize=9)
    plt.grid(True, alpha=0.3)
    plt.tight_layout()
    plt.show()

